import{_ as e,o as d,c as r,a2 as a}from"./chunks/framework.hwbV7reR.js";const h=JSON.parse('{"title":"Конфигурация","description":"","frontmatter":{},"headers":[],"relativePath":"configuration.md","filePath":"configuration.md","lastUpdated":1791695486000}'),i={name:"configuration.md"};function o(n,t,s,l,c,g){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="конфигурация" tabindex="-1">Конфигурация <a class="header-anchor" href="#конфигурация" aria-label="Permalink to &quot;Конфигурация&quot;">​</a></h1><p>По умолчанию <code>/etc/vpn-orchestrator/settings.json</code>. Можно передать <code>--settings</code> перед подкомандой или <code>ORCHESTRATOR_SETTINGS</code>. Системные службы используют фиксированный путь; <code>start/stop/restart</code> управляют именно этой установкой.</p><p>Обязательны <code>state_directory</code> и <code>backend_token_file</code> — абсолютные пути. <code>schema_version</code> сейчас 1. Неизвестные поля, неверные типы и небезопасные границы отклоняются. Ключи — приватные обычные файлы без symlink. Секретные значения и исходные данные ошибки валидации не печатаются.</p><p><code>nodes</code> поддерживается для однократного импорта старой установки. После инициализации реестра источником истины становится SQLite, включая пустой список. Старые bootstrap ключи после их ротации больше не требуются. Для новых установок <code>nodes</code> не нужен: используйте <code>add server</code>. <code>admin_token_file</code> принят лишь для совместимости и игнорируется.</p><h2 id="настраиваемая-политика" tabindex="-1">Настраиваемая политика <a class="header-anchor" href="#настраиваемая-политика" aria-label="Permalink to &quot;Настраиваемая политика&quot;">​</a></h2><p>Все значения целочисленные, длительности в секундах. В <code>policy</code> доступны:</p><table tabindex="0"><thead><tr><th>Путь</th><th style="text-align:right;">По умолчанию</th><th style="text-align:right;">Допустимо</th></tr></thead><tbody><tr><td>agents.operation_timeout_seconds</td><td style="text-align:right;">30</td><td style="text-align:right;">5–60</td></tr><tr><td>agents.queue_timeout_seconds</td><td style="text-align:right;">2</td><td style="text-align:right;">1–5</td></tr><tr><td>agents.max_concurrent_requests</td><td style="text-align:right;">16</td><td style="text-align:right;">2–64</td></tr><tr><td>agents.max_concurrent_per_node</td><td style="text-align:right;">4</td><td style="text-align:right;">1–32, строго меньше общего лимита</td></tr><tr><td>agents.max_pending_per_node</td><td style="text-align:right;">8</td><td style="text-align:right;">1–64, не меньше узловой параллельности и меньше общего pending-лимита</td></tr><tr><td>agents.max_pending_requests</td><td style="text-align:right;">64</td><td style="text-align:right;">2–256, не меньше общего лимита</td></tr><tr><td>agents.connect_timeout_seconds</td><td style="text-align:right;">4</td><td style="text-align:right;">1–10</td></tr><tr><td>agents.response_timeout_seconds</td><td style="text-align:right;">12</td><td style="text-align:right;">1–15</td></tr><tr><td>recovery.cooldown_seconds</td><td style="text-align:right;">1800</td><td style="text-align:right;">60–86400</td></tr><tr><td>recovery.reconcile_batch_size</td><td style="text-align:right;">16</td><td style="text-align:right;">1–100</td></tr><tr><td>selection.observation_workers</td><td style="text-align:right;">4</td><td style="text-align:right;">1–16</td></tr><tr><td>selection.observation_max_age_seconds</td><td style="text-align:right;">30</td><td style="text-align:right;">1–300</td></tr><tr><td>leases.duration_seconds</td><td style="text-align:right;">90</td><td style="text-align:right;">90–120</td></tr><tr><td>leases.max_node_lease_seconds</td><td style="text-align:right;">120</td><td style="text-align:right;">120–300</td></tr><tr><td>leases.fence_grace_seconds</td><td style="text-align:right;">125</td><td style="text-align:right;">125–600</td></tr><tr><td>leases.heartbeat_workers</td><td style="text-align:right;">64</td><td style="text-align:right;">фиксировано 64</td></tr></tbody></table><p>Старые настройки без новых полей принимаются с указанными значениями по умолчанию. Новые ограничения меняют поведение при перегрузке и медленных ответах. Изменения применяются после перезапуска API и рабочих процессов; не изменяйте настройки одного процесса отдельно. Защитное ожидание равно max_node_lease_seconds + fence_grace_seconds. Его минимальная граница связана с watchdog и остановкой на узле; не является обычным timeout HTTP.</p><p>Периоды systemd timers, ограничения выполнения worker и версия протокола разрешений остаются частью deployment contract. Их нельзя независимо сокращать через JSON. HTTP timeout не означает, что мутация не произошла: автоматических транспортных повторов с новым ключом нет. Незавершённое переключение продолжает ту же операцию.</p><p>Для клиента отдельно действуют порог обнаружения проблем и количество попыток. Эти значения не объявляются управляемыми оркестратором, пока нет согласованного контракта доставки политики приложениям.</p><h2 id="проверка" tabindex="-1">Проверка <a class="header-anchor" href="#проверка" aria-label="Permalink to &quot;Проверка&quot;">​</a></h2><p><code>config validate --structure-only</code> проверяет структуру без чтения секретов. <code>config validate</code> также проверяет приватные ключи и привязки журнала, не меняя БД. <code>config validate --probe</code> дополнительно обращается к агентам для проверки идентичности.</p>',12)])])}const x=e(i,[["render",o]]);export{h as __pageData,x as default};
